using System.Collections;using Alterverse.Audio;using Alterverse.Combat;using Alterverse.Shop;using Alterverse.Visuals;using UnityEngine;
namespace Alterverse.Characters
{
[RequireComponent(typeof(Health))]public sealed class BaseRecall:MonoBehaviour
{
[SerializeField,Min(1f)]private float channelDuration=5f;[SerializeField]private float movementCancelDistance=.18f;private Health health;private Vector3 spawnPoint,channelStart;private float previousHealth;private Coroutine recallRoutine;private RecallCosmeticVfx cosmeticVfx;public bool IsRecalling=>recallRoutine!=null;public float Progress{get;private set;}
private void Awake(){health=GetComponent<Health>();spawnPoint=transform.position;health.Died+=CancelRecall;if(RecallCosmeticEntitlement.Owned)cosmeticVfx=gameObject.AddComponent<RecallCosmeticVfx>();}private void OnDestroy(){if(health!=null)health.Died-=CancelRecall;}public void BeginRecall(){if(health==null||health.IsDead||IsRecalling)return;DimensionAudio.Play(DimensionSound.RecallStart,.55f);recallRoutine=StartCoroutine(RecallRoutine());}public void CancelRecall(){bool wasRecalling=recallRoutine!=null;if(recallRoutine!=null)StopCoroutine(recallRoutine);recallRoutine=null;Progress=0f;cosmeticVfx?.SetRecallState(false,0f);if(wasRecalling)DimensionAudio.Play(DimensionSound.RecallCancel,.45f);}
private IEnumerator RecallRoutine(){channelStart=transform.position;previousHealth=health.Current;Progress=0f;cosmeticVfx?.SetRecallState(true,0f);while(Progress<1f){float currentHealth=health.Current;bool tookDamage=currentHealth<previousHealth-.01f;previousHealth=currentHealth;if(health.IsDead||tookDamage||HorizontalDistance(channelStart,transform.position)>movementCancelDistance){recallRoutine=null;Progress=0f;cosmeticVfx?.SetRecallState(false,0f);DimensionAudio.Play(DimensionSound.RecallCancel,.45f);yield break;}if(Time.timeScale>0f)Progress+=Time.deltaTime/channelDuration;cosmeticVfx?.SetRecallState(true,Progress);yield return null;}cosmeticVfx?.SetRecallState(false,1f);DimensionAudio.Play(RecallCosmeticEntitlement.Owned?DimensionSound.RealityShatter:DimensionSound.RecallComplete,RecallCosmeticEntitlement.Owned?.78f:.58f);CharacterController controller=GetComponent<CharacterController>();if(controller!=null)controller.enabled=false;transform.position=spawnPoint;if(controller!=null)controller.enabled=true;recallRoutine=null;Progress=0f;}private static float HorizontalDistance(Vector3 a,Vector3 b){a.y=0;b.y=0;return Vector3.Distance(a,b);}
}
}
